('1', 'INC-OLIVZ-20261019-0001', NULL, '2', 'Olivz by Danube', 'OLIVZ', '2', 'Mohammed Ahmed', 'Patrol Security Officer (SG1074)', '2026-10-19', '19:21', 'Day', 'High', '[\"Incident\"]', '[]', '', '[\"Fire & Safety\"]', '', 'Fire in the building', 'There is a fire in the building', '[]', '', 'Submitted', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-19 19:21:13', '2026-10-20 20:06:21'),
('7', 'INC-OLIVZ-20261020-0001', NULL, '2', 'Olivz by Danube', 'OLIVZ', '4', 'Shiraz Ahmed', 'Security Supervisor (SG1558)', '2026-10-20', '20:33', 'Day', 'Medium', '[]', '[]', '', '[\"Utilities & Building\"]', '', 'House keeping is not collected garbage on time from block 1 garbage room', '<div>Incident Description: Housekeeping has not been collecting garbage from the garbage room for a long time. This issue has already been reported to FM Manager Avinash Sir, but no action has been taken so far.</div><div>Required Action: Kindly look into this matter and instruct the housekeeping team to collect the garbage regularly and maintain proper cleanliness and hygiene in the garbage room.</div>', '[\"Client Management\"]', '', 'Submitted', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-20 20:37:17', '2026-10-20 20:38:17'),
