-- ====================================================================
-- ULTIMATE SECURITY SERVICES (USS) - COMPLETE PRODUCTION DATABASE
-- Pre-seeded with 500 Enterprise Checkpoints, 50 Supervisors, 250 Guards,
-- Checkpoint QR Tokens, Camp Hub, and Completed Site Visit Records
-- Charset: utf8mb4 / Collation: utf8mb4_unicode_ci
-- ====================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `admins`;
CREATE TABLE `admins` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(100) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `totp_secret_encrypted` text DEFAULT NULL,
  `totp_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `full_name` varchar(150) NOT NULL DEFAULT 'Super Administrator',
  `email` varchar(150) DEFAULT NULL,
  `must_change_password` tinyint(1) NOT NULL DEFAULT 1,
  `last_login_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE `system_settings` (
  `id` varchar(50) NOT NULL,
  `company_name` varchar(255) NOT NULL DEFAULT 'ULTIMATE SECURITY SERVICES',
  `tagline` varchar(255) NOT NULL DEFAULT 'Total Security Solutions',
  `address_line` text DEFAULT NULL,
  `phone` varchar(100) NOT NULL DEFAULT '+971 4 251 0050',
  `email` varchar(100) NOT NULL DEFAULT 'ops@ultimatesecurity.ae',
  `website` varchar(150) DEFAULT 'https://www.sprinzo.in',
  `logo_url` varchar(255) DEFAULT 'assets/images/logo.png',
  `timezone` varchar(100) NOT NULL DEFAULT 'Asia/Dubai',
  `shift_options` text DEFAULT NULL,
  `cause_options` text DEFAULT NULL,
  `disciplinary_options` text DEFAULT NULL,
  `incident_options` text DEFAULT NULL,
  `notified_options` text DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `supervisor_remarks_min_length` int(11) NOT NULL DEFAULT 20,
  `supervisor_session_hours` int(11) NOT NULL DEFAULT 16,
  `supervisor_location_check_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `supervisor_alert_email_recipients` text DEFAULT NULL,
  `supervisor_visit_form_schema` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `camps`;
CREATE TABLE `camps` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `camp_code` varchar(50) NOT NULL,
  `camp_name` varchar(200) NOT NULL,
  `location` text DEFAULT NULL,
  `qr_token` varchar(100) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `camp_code` (`camp_code`),
  UNIQUE KEY `qr_token` (`qr_token`),
  KEY `idx_camp_code` (`camp_code`),
  KEY `idx_camp_token` (`qr_token`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sites`;
CREATE TABLE `sites` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `code` varchar(50) NOT NULL,
  `type` enum('Commercial','Residential','Hospital') NOT NULL DEFAULT 'Commercial',
  `address` text DEFAULT NULL,
  `latitude` varchar(100) DEFAULT NULL,
  `longitude` varchar(100) DEFAULT NULL,
  `client_name` varchar(150) DEFAULT NULL,
  `client_contact` varchar(150) DEFAULT NULL,
  `active_qr_token` varchar(100) NOT NULL,
  `min_visits_per_week` int(11) NOT NULL DEFAULT 7,
  `min_night_visits_per_week` int(11) NOT NULL DEFAULT 2,
  `min_minutes_per_visit` int(11) NOT NULL DEFAULT 20,
  `max_minutes_per_visit` int(11) NOT NULL DEFAULT 120,
  `supervisor_qr_token` varchar(100) DEFAULT NULL,
  `token_hmac` varchar(64) DEFAULT NULL,
  `token_encrypted` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  UNIQUE KEY `active_qr_token` (`active_qr_token`),
  KEY `idx_sites_code` (`code`),
  KEY `idx_sites_qr` (`active_qr_token`),
  KEY `idx_sites_active` (`is_active`),
  KEY `idx_sites_token_hmac` (`token_hmac`)
) ENGINE=InnoDB AUTO_INCREMENT=504 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;







DROP TABLE IF EXISTS `guards`;
CREATE TABLE `guards` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `staff_id` varchar(50) NOT NULL,
  `full_name` varchar(150) NOT NULL,
  `designation` varchar(100) NOT NULL DEFAULT 'Security Guard',
  `is_supervisor` tinyint(1) NOT NULL DEFAULT 0,
  `assigned_camp_id` int(10) unsigned DEFAULT NULL,
  `username` varchar(100) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `last_login_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_id` (`staff_id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_guards_username` (`username`),
  KEY `idx_guards_staff_id` (`staff_id`)
) ENGINE=InnoDB AUTO_INCREMENT=305 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





DROP TABLE IF EXISTS `guard_site_assignments`;
CREATE TABLE `guard_site_assignments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `guard_id` int(10) unsigned NOT NULL,
  `site_id` int(10) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_guard_site` (`guard_id`,`site_id`),
  KEY `idx_assignment_guard` (`guard_id`),
  KEY `idx_assignment_site` (`site_id`),
  CONSTRAINT `fk_assignment_guard` FOREIGN KEY (`guard_id`) REFERENCES `guards` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_assignment_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `supervisor_duties`;
CREATE TABLE `supervisor_duties` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `duty_ref` varchar(100) NOT NULL,
  `supervisor_id` int(10) unsigned NOT NULL,
  `camp_id` int(10) unsigned NOT NULL,
  `duty_date` date NOT NULL,
  `shift_type` enum('Day','Night') NOT NULL DEFAULT 'Day',
  `camp_out_time` datetime NOT NULL,
  `camp_in_time` datetime DEFAULT NULL,
  `status` enum('Active','Completed') NOT NULL DEFAULT 'Active',
  `total_sites` int(11) NOT NULL DEFAULT 0,
  `total_minutes` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `duty_ref` (`duty_ref`),
  KEY `idx_duty_sup_date` (`supervisor_id`,`duty_date`),
  KEY `idx_duty_status` (`status`),
  KEY `fk_duty_camp` (`camp_id`),
  CONSTRAINT `fk_duty_camp` FOREIGN KEY (`camp_id`) REFERENCES `camps` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_duty_supervisor` FOREIGN KEY (`supervisor_id`) REFERENCES `guards` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `supervisor_visits`;
CREATE TABLE `supervisor_visits` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `visit_ref` varchar(100) DEFAULT NULL,
  `duty_id` int(10) unsigned NOT NULL,
  `supervisor_id` int(10) unsigned NOT NULL,
  `site_id` int(10) unsigned NOT NULL,
  `time_in` datetime NOT NULL,
  `time_out` datetime DEFAULT NULL,
  `minutes_spent` int(11) NOT NULL DEFAULT 0,
  `travel_minutes_from_previous` int(11) NOT NULL DEFAULT 0,
  `remarks` text DEFAULT NULL,
  `purpose_of_visit` varchar(50) NOT NULL DEFAULT 'Routine',
  `guards_count` int(11) NOT NULL DEFAULT 0,
  `guards_attendance` varchar(50) NOT NULL DEFAULT 'All present',
  `guards_names` text DEFAULT NULL,
  `rating_turnout` varchar(20) NOT NULL DEFAULT 'OK',
  `rating_records` varchar(20) NOT NULL DEFAULT 'OK',
  `rating_condition` varchar(20) NOT NULL DEFAULT 'OK',
  `rating_equipment` varchar(20) NOT NULL DEFAULT 'OK',
  `has_issues` tinyint(1) NOT NULL DEFAULT 0,
  `issues_action_taken` text DEFAULT NULL,
  `manual_timeout_requested` tinyint(1) NOT NULL DEFAULT 0,
  `manual_timeout_time` datetime DEFAULT NULL,
  `manual_timeout_reason` text DEFAULT NULL,
  `manual_timeout_status` enum('None','Pending','Approved','Rejected') NOT NULL DEFAULT 'None',
  `corrected_by_admin_id` int(10) unsigned DEFAULT NULL,
  `correction_notes` text DEFAULT NULL,
  `site_report` text DEFAULT NULL,
  `status` enum('In Progress','Completed') NOT NULL DEFAULT 'In Progress',
  `is_draft` tinyint(1) NOT NULL DEFAULT 0,
  `is_offline_sync` tinyint(1) NOT NULL DEFAULT 0,
  `client_scan_time` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `visit_ref` (`visit_ref`),
  KEY `idx_visit_duty` (`duty_id`),
  KEY `idx_visit_sup` (`supervisor_id`,`time_in`),
  KEY `idx_visit_site` (`site_id`,`time_in`),
  KEY `idx_visit_status` (`status`),
  CONSTRAINT `fk_visit_duty` FOREIGN KEY (`duty_id`) REFERENCES `supervisor_duties` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_visit_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_visit_sup` FOREIGN KEY (`supervisor_id`) REFERENCES `guards` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



DROP TABLE IF EXISTS `incidents`;
CREATE TABLE `incidents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ref_number` varchar(100) NOT NULL,
  `idempotency_key` varchar(100) DEFAULT NULL,
  `site_id` int(10) unsigned NOT NULL,
  `site_name` varchar(200) NOT NULL,
  `site_code` varchar(50) NOT NULL,
  `guard_id` int(10) unsigned DEFAULT NULL,
  `reported_by_name` varchar(150) NOT NULL,
  `reported_by_designation` varchar(100) NOT NULL,
  `incident_date` date NOT NULL,
  `incident_time` varchar(10) NOT NULL,
  `shift` varchar(50) NOT NULL DEFAULT 'Day',
  `priority` enum('Critical','High','Medium','Low') NOT NULL DEFAULT 'Medium',
  `cause_main` text DEFAULT NULL,
  `disciplinary_reasons` text DEFAULT NULL,
  `disciplinary_other_text` text DEFAULT NULL,
  `incident_types` text DEFAULT NULL,
  `incident_other_text` text DEFAULT NULL,
  `summary_line` varchar(255) NOT NULL,
  `description` longtext NOT NULL,
  `who_notified` text DEFAULT NULL,
  `notified_other_text` text DEFAULT NULL,
  `status` enum('Submitted','Under Review','Follow-up Required','Resolved','Submitted to Client') NOT NULL DEFAULT 'Submitted',
  `site_supervisor_name` varchar(150) DEFAULT NULL,
  `site_supervisor_id` varchar(100) DEFAULT NULL,
  `site_supervisor_signature` text DEFAULT NULL,
  `site_supervisor_date` date DEFAULT NULL,
  `recommendation_action_taken` text DEFAULT NULL,
  `operations_manager_name` varchar(150) DEFAULT NULL,
  `operations_manager_signature` text DEFAULT NULL,
  `operations_manager_date` date DEFAULT NULL,
  `client_manager_action_taken` text DEFAULT NULL,
  `client_manager_name` varchar(150) DEFAULT NULL,
  `client_manager_signature` text DEFAULT NULL,
  `client_manager_date` date DEFAULT NULL,
  `submitted_to_client_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `ref_number` (`ref_number`),
  KEY `idx_incidents_site` (`site_id`),
  KEY `idx_incidents_date` (`incident_date`),
  KEY `idx_incidents_status` (`status`),
  KEY `idx_incidents_priority` (`priority`),
  KEY `idx_incidents_deleted` (`deleted_at`),
  KEY `idx_incidents_ref` (`ref_number`),
  KEY `idx_incidents_active_created` (`deleted_at`,`created_at`,`id`),
  KEY `idx_incidents_guard_perf` (`guard_id`,`deleted_at`,`created_at`),
  KEY `idx_incidents_site_perf` (`site_id`,`deleted_at`,`incident_date`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `actor_type` varchar(50) NOT NULL DEFAULT 'SUPER_ADMIN',
  `actor_id` varchar(100) DEFAULT NULL,
  `actor_name` varchar(150) DEFAULT NULL,
  `action` varchar(100) NOT NULL,
  `target_type` varchar(100) DEFAULT NULL,
  `target_id` varchar(100) DEFAULT NULL,
  `details` text DEFAULT NULL,
  `previous_hash` varchar(64) DEFAULT NULL,
  `record_hash` varchar(64) DEFAULT NULL,
  `ip_address` varchar(50) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_created` (`created_at`),
  KEY `idx_audit_action` (`action`),
  KEY `idx_audit_chain_perf` (`id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



SET FOREIGN_KEY_CHECKS = 1;
